import{_ as t,o as a,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"バージョン情報と更新","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. コンポーネントバージョンと概要","slug":"_1-コンポーネントバージョンと概要","link":"#_1-コンポーネントバージョンと概要","children":[]},{"level":2,"title":"2. データディレクトリと 5 世代バックアップローテーション","slug":"_2-データディレクトリと-5-世代バックアップローテーション","link":"#_2-データディレクトリと-5-世代バックアップローテーション","children":[{"level":3,"title":"ユーザーデータディレクトリ","slug":"ユーザーデータディレクトリ","link":"#ユーザーデータディレクトリ","children":[]},{"level":3,"title":"マシンデータディレクトリ","slug":"マシンデータディレクトリ","link":"#マシンデータディレクトリ","children":[]},{"level":3,"title":"ディレクトリの配置構成","slug":"ディレクトリの配置構成","link":"#ディレクトリの配置構成","children":[]}]},{"level":2,"title":"3. 更新の確認と自動アップデート","slug":"_3-更新の確認と自動アップデート","link":"#_3-更新の確認と自動アップデート","children":[]}],"relativePath":"ja-JP/user-guide/settings/about.md","filePath":"ja-JP/user-guide/settings/about.md","lastUpdated":1791112464000}'),o={name:"ja-JP/user-guide/settings/about.md"};function i(s,e,n,d,c,g){return a(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="バージョン情報と更新" tabindex="-1">バージョン情報と更新 <a class="header-anchor" href="#バージョン情報と更新" aria-label="Permalink to &quot;バージョン情報と更新&quot;">​</a></h1><p>バージョン情報画面では、Lertaro の稼働環境に関する完全なバージョン情報、各種データディレクトリへのアクセスリンク、およびオンラインでの更新確認・自動アップデート機能を提供します。設定画面は <strong>設定 → バージョン情報</strong> です。</p><h2 id="_1-コンポーネントバージョンと概要" tabindex="-1">1. コンポーネントバージョンと概要 <a class="header-anchor" href="#_1-コンポーネントバージョンと概要" aria-label="Permalink to &quot;1. コンポーネントバージョンと概要&quot;">​</a></h2><p>画面上部には、Lertaro を構成する 4 大コンポーネントのバージョン番号が表示されます。</p><ul><li><strong>App バージョン</strong>：フロントエンド WPF UI のバージョン。</li><li><strong>Core バージョン</strong>：検索・インデックス処理コアライブラリのバージョン。</li><li><strong>Service バージョン</strong>：バックグラウンド Windows サービスのバージョン（文字色が現在の接続健全性を動的に反映）。</li><li><strong>CLI バージョン</strong>：コマンドラインツール <code>lff</code> のバージョン。</li></ul><p>下部には、公式サイト、GitHub リポジトリ、およびオンラインドキュメントへのリンクが配置されています。</p><h2 id="_2-データディレクトリと-5-世代バックアップローテーション" tabindex="-1">2. データディレクトリと 5 世代バックアップローテーション <a class="header-anchor" href="#_2-データディレクトリと-5-世代バックアップローテーション" aria-label="Permalink to &quot;2. データディレクトリと 5 世代バックアップローテーション&quot;">​</a></h2><p>エクスプローラーで直接開くことができる 2 つのリンクが用意されています（フォルダーが存在しない場合は自動作成されます）：</p><h3 id="ユーザーデータディレクトリ" tabindex="-1">ユーザーデータディレクトリ <a class="header-anchor" href="#ユーザーデータディレクトリ" aria-label="Permalink to &quot;ユーザーデータディレクトリ&quot;">​</a></h3><ul><li><strong>保存内容</strong>：ユーザー設定（<code>user-settings.json</code>）、検索・キーワード履歴、ユーザーキャッシュ、セキュリティ証明書。</li><li><strong>5 世代バックアップローテーション</strong>：設定保存時、既存の設定ファイルが <code>user-settings.json.bak.1</code> へとローテーションされ、最大 <code>.bak.5</code> まで自動保持されます。誤設定やクラッシュ時も直近 5 回分のバックアップから即座に復元可能です。</li></ul><h3 id="マシンデータディレクトリ" tabindex="-1">マシンデータディレクトリ <a class="header-anchor" href="#マシンデータディレクトリ" aria-label="Permalink to &quot;マシンデータディレクトリ&quot;">​</a></h3><ul><li><strong>保存内容</strong>：マシン全体の設定（<code>machine-settings.json</code>）、永続化された物理インデックスキャッシュ、バックグラウンドサービスのログ。</li></ul><h3 id="ディレクトリの配置構成" tabindex="-1">ディレクトリの配置構成 <a class="header-anchor" href="#ディレクトリの配置構成" aria-label="Permalink to &quot;ディレクトリの配置構成&quot;">​</a></h3><ul><li><strong>インストーラー版</strong>：ユーザーデータは <code>%LocalAppData%\\Lertaro</code>、マシンデータは <code>%ProgramData%\\Lertaro</code> に保存されます。</li><li><strong>ポータブル版</strong>：実行ファイルと同階層の <code>Data\\Users\\&lt;SID hash&gt;</code> および <code>Data\\Machine</code> に保存され、システムディレクトリからは完全に分離されています（詳細は <a href="./../getting-started.html"><strong>ポータブル版のデータ分離</strong></a> を参照）。</li></ul><h2 id="_3-更新の確認と自動アップデート" tabindex="-1">3. 更新の確認と自動アップデート <a class="header-anchor" href="#_3-更新の確認と自動アップデート" aria-label="Permalink to &quot;3. 更新の確認と自動アップデート&quot;">​</a></h2><ul><li><strong>更新を確認</strong>：オンラインで新しいリリースを問い合わせ、結果をボタン上に表示します（「更新を確認中...」 → 「最新バージョンです」または新バージョンの案内）。</li><li><strong>新バージョン検出時の適用方法</strong>： <ul><li><strong>サイレント自動更新</strong> —— バックグラウンドで新バージョンをダウンロードして自動置換し、完了後に再起動します。</li><li><strong>ダウンロードページへ移動</strong> —— ブラウザーで GitHub Releases を開き、手動でパッケージを取得します。</li></ul></li><li><strong>権限に関するガイダンス</strong>：標準ユーザー権限でサービスの停止・更新が制限されている場合、手動ダウンロードを案内する通知が表示されます。</li></ul>',16)])])}const _=t(o,[["render",i]]);export{h as __pageData,_ as default};
